import { VIEWBOX_START_X
 , VIEWBOX_START_Y} from 'constants'

export
 { sizeDataDec
 , calculateCanvasSize
 }


// Return the object includes:
// - width
// - height
// - viewbox

// viewbox: string
// String value for 'viewBox'.
// The x and y positions of 'viewBox' are fixed at 0, formatted as '0 0 width height'.
// The [0]-indexed group contains one or two lines representing the canvas size.
// Values are calculated from absolute coordinates.
// Used in 'crop-side-margin.js'.


function sizeDataDec(linesDataMapIndexZero) {
 // absDvalsObj: {x1: Array(2), y1: Array(2), x2: Array(2), y2: Array(2)}
 // encodedDvals: "NWrTPcKpRSjaX"
 // groupColors: {g_stroke: '#AAAAAA', gOpacity: 1, gStrokeOpacity: 1}
 // relDvalsObj: {x1: Array(2), y1: Array(2), x2: Array(2), y2: Array(2)}
 // encodingMethodFlag: '1'
 // widthsAndCounts: {firstline: Array(1), lastline: Array(1), width: Array(1)}
 // [[Prototype]]: Object

 const absDvalsObj = linesDataMapIndexZero.absDvalsObj

 // Get the 'width' and 'height' attrs
 let sizeDataObj = calculateCanvasSize(absDvalsObj)

 // Define the 'viewBox' value
 const viewboxStr = `${VIEWBOX_START_X} ${VIEWBOX_START_Y} ${sizeDataObj.width} ${sizeDataObj.height}`

 // Add the 'viewBox' and include 'width' and 'height' for completeness
 sizeDataObj = { viewbox: viewboxStr, ...sizeDataObj }

 return sizeDataObj
}


function calculateCanvasSize(d) {
 //console.log('d: ', d)

 // e.g.: 127 x 127
 // x1: (2) [63, 64]
 // x2: (2) [63, 64]
 // y1: (2) [0, 0]
 // y2: (2) [127, 127]
 // [[Prototype]]: Object

 // e.g.: 128 x 128
 // x1: (1) [128],
 // x2: (1) [64],
 // y1: (1) [0],
 // y2: (1) [64]
 // [[Prototype]]: Object


 let width, height

 if (d.x1.length === 2) {
 // Vertical strokes
 if (d.x1[0] === d.x2[0]) {
 width = d.x1[0] + d.x1[1]
 height = d.y1[0] + d.y2[0]
 }
 // Horizontal strokes
 else if (d.y1[0] === d.y2[0]) {
 width = d.y1[0] + d.y1[1]
 height = d.x1[0] + d.x2[0]
 }
 }

 else if (d.x1.length === 1) {
 // Vertical stroke
 if (d.x1[0] === d.x2[0]) {
 width = d.y1[0] + d.y2[0]
 height = d.x1[0] + d.x2[0]
 }
 // Horizontal stroke
 else if (d.y1[0] === d.y2[0]) {
 width = d.x1[0] + d.x2[0]
 height = d.y1[0] + d.y2[0]
 }
 }

 else {
 console.error("Invalid coordinates.")
 }

 return { width, height }
}

